function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function request(path, options) {
  const response = await fetch(apiOrigin() + path, { headers: { Accept: 'application/json', 'Content-Type': 'application/json' }, ...options })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  if (response.status === 204) return {}
  return response.json()
}

function redact(payload) {
  if (payload && typeof payload === 'object' && typeof payload.python_source === 'string') delete payload.python_source
  return payload
}

async function run(input) {
  if (input.operation === 'save') {
    if (input.confirm_write !== true) throw new Error('Saving a strategy requires an explicit user request and confirm_write=true')
    const id = String(input.strategy_id || '').trim()
    const yaml = String(input.yaml || '').trim()
    if (!id || !yaml) throw new Error('strategy_id and yaml are required for save')
    const validation = await request('/api/strategies/validate', { method: 'POST', body: JSON.stringify({ yaml, ...(input.python_source !== undefined ? { python_source: String(input.python_source) } : {}) }) })
    if (!validation.valid) throw new Error('Strategy validation failed')
    if (validation.name !== id) throw new Error('strategy_id must match the strategy name in yaml')
    const payload = await request('/api/strategies/' + encodeURIComponent(id), { method: 'PUT', body: JSON.stringify({ yaml: validation.normalized_yaml, ...(input.python_source !== undefined ? { python_source: String(input.python_source) } : {}) }) })
    return redact(payload)
  }
  if (input.operation === 'clone') {
    if (input.confirm_write !== true) throw new Error('Cloning a strategy requires an explicit user request and confirm_write=true')
    const source = String(input.source_strategy_id || '').trim()
    const target = String(input.target_strategy_id || '').trim()
    if (!source || !target) throw new Error('source_strategy_id and target_strategy_id are required for clone')
    const payload = await request('/api/strategies/' + encodeURIComponent(source) + '/clone', { method: 'POST', body: JSON.stringify({ target_id: target }) })
    return redact(payload)
  }
  if (input.operation === 'delete') {
    if (input.confirm_delete !== true) throw new Error('Deleting a strategy requires an explicit user request and confirm_delete=true')
    const id = String(input.strategy_id || '').trim()
    if (!id) throw new Error('strategy_id is required for delete')
    await request('/api/strategies/' + encodeURIComponent(id), { method: 'DELETE' })
    return { deleted: true, strategy_id: id }
  }
  throw new Error('Unsupported strategy mutation operation')
}
